UPDATE item_model_import SET image=image||'","view":"三面図","note":"Blockbench用アイテム参考 v1（AI生成）。赤ちゃん恐竜の共通モデルを6匹配置。頭・胴・左右の脚・腕・尾を分ける案。これは移動する生物のモデルで、通常の手持ちアイテムとは導入形式が異なる。使用するエンティティ方式と出力形式は制作時に確定する。 正面・側面・背面を中心に形・厚み・配色を見る資料です。厳密な投影図ではなく、方向間の差は制作時に整合させます。完成したモデルではありません。","source":""}' WHERE title='恐竜研究所鬼ごっこ';
INSERT INTO idea_references(idea_id,kind,content)
SELECT ideas.id,'mission','{"brief":"","images":[]}' FROM ideas JOIN item_model_import ON ideas.title=item_model_import.title
WHERE NOT EXISTS(SELECT 1 FROM idea_references WHERE idea_id=ideas.id AND kind='mission');
UPDATE idea_references SET content=json_set(content,
'$.brief',json_extract(content,'$.brief')||(SELECT addition FROM item_model_import JOIN ideas ON ideas.title=item_model_import.title WHERE ideas.id=idea_references.idea_id),
'$.images[#]',json((SELECT image FROM item_model_import JOIN ideas ON ideas.title=item_model_import.title WHERE ideas.id=idea_references.idea_id)))
WHERE kind='mission' AND idea_id IN (SELECT id FROM ideas JOIN item_model_import ON ideas.title=item_model_import.title)
AND json_array_length(content,'$.images')<6 AND instr(content,'【Blockbench用アイテム参考 v1】')=0
AND length(json_extract(content,'$.brief'))+(SELECT length(addition) FROM item_model_import JOIN ideas ON ideas.title=item_model_import.title WHERE ideas.id=idea_references.idea_id)<=3000;
DROP TABLE item_model_import;
